package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_initials_TriageGen1Test {

    @Test
    public void testInitials_NullString() {
        assertNull(WordUtils.initials(null, new char[]{',', ' '}));
    }

    @Test
    public void testInitials_EmptyString() {
        assertEquals("", WordUtils.initials("", new char[]{',', ' '}));
    }

    @Test
    public void testInitials_NullDelimiters() {
        // When delimiters is null, isDelimiter(ch, null) is called. 
        // Assuming isDelimiter returns false for null delimiters.
        // If isDelimiter handles null, we test the logic flow.
        // Based on the provided code, if delimiters is null, the second if block is skipped.
        // The loop runs, isDelimiter returns false, lastWasGap is true, so it picks up characters.
        assertEquals("abc", WordUtils.initials("abc", null));
    }

    @Test
    public void testInitials_EmptyDelimiters() {
        assertEquals("", WordUtils.initials("abc def", new char[]{}));
    }

    @Test
    public void testInitials_StandardCase() {
        char[] delimiters = {' ', '.', ','};
        assertEquals("adf", WordUtils.initials("a b.c,d", delimiters));
    }

    @Test
    public void testInitials_NoDelimitersInString() {
        char[] delimiters = {' '};
        assertEquals("a", WordUtils.initials("a", delimiters));
        assertEquals("abc", WordUtils.initials("abc", delimiters));
    }

    @Test
    public void testInitials_LeadingDelimiters() {
        char[] delimiters = {' '};
        assertEquals("ab", WordUtils.initials("  a b", delimiters));
    }

    @Test
    public void testInitials_TrailingDelimiters() {
        char[] delimiters = {' '};
        assertEquals("ab", WordUtils.initials("a b  ", delimiters));
    }

    @Test
    public void testInitials_MultipleConsecutiveDelimiters() {
        char[] delimiters = {' ', '\t'};
        assertEquals("abc", WordUtils.initials("a  \t b c", delimiters));
    }

    @Test
    public void testInitials_OnlyDelimiters() {
        char[] delimiters = {' ', '.'};
        assertEquals("", WordUtils.initials(" .  . ", delimiters));
    }

    @Test
    public void testInitials_SingleCharacterString() {
        char[] delimiters = {' '};
        assertEquals("a", WordUtils.initials("a", delimiters));
    }

    @Test
    public void testInitials_AllCharsAreDelimiters() {
        char[] delimiters = {'a', 'b', 'c'};
        assertEquals("", WordUtils.initials("abc", delimiters));
    }
}
